<?php

declare(strict_types=1);

if (PHP_SAPI !== 'cli') {
    http_response_code(404);
    exit;
}

$manifest = json_decode(<<<'WZ_CITY_PAYLOAD'
{
  "includes/cities.php": {
    "previous_sha256": null,
    "sha256": "ed4a44fa1aea0aa7621b03ad9a309e7a602ad409052e674fcc5cc33182677367",
    "content_gzip_base64": ""
  },
  "assets/css/cities.css": {
    "previous_sha256": null,
    "sha256": "c47c2289f1f5d036359e2ea691428ac1f26c80ff6d851ab70291388e6d730e9f",
    "content_gzip_base64": ""
  },
  "cities.php": {
    "previous_sha256": null,
    "sha256": "47f86a413f6ac7cbef9708f682e3b921e06ab9d527aa7bbb4b14e6e8c0098210",
    "content_gzip_base64": ""
  },
  "city.php": {
    "previous_sha256": "007ad5455e4a1985173c0eabf30c1d5c52be3c216874b6f2e8b274643be48642",
    "sha256": "fd8a122dc76babdd513dc46d272a67969bf08aebf1ff6f6435c196c632da1938",
    "content_gzip_base64": "",
    "previous_content_gzip_base64": ""
  },
  "index.php": {
    "previous_sha256": "dfa4ef9778d752892c415040d65383de034ac9962d98cd75fdcf090c7d03726f",
    "sha256": "a747be84f3f26c21494f2e4b5f5e02975541c73b512383ec150794bb725d0519",
    "content_gzip_base64": "",
    "previous_content_gzip_base64": ""
  },
  "sitemap.php": {
    "previous_sha256": "eb55a0e99640871205fc192d786cf10f53417e7ff0caf5a1e844b8f49d9e5ef1",
    "sha256": "c38455de7fa24a61e48c06e45d36cc7de044ebb1898641c4929643ff81dac30b",
    "content_gzip_base64": "",
    "previous_content_gzip_base64": ""
  }
}
WZ_CITY_PAYLOAD, true, 512, JSON_THROW_ON_ERROR);

$root = realpath(getcwd() ?: '');
$backupDirectory = '';
$originals = [];
$changes = [];
$staged = [];
$installed = [];
$modes = [];
$lock = null;

try {
    if (!$root || !is_file($root . '/includes/bootstrap.php') || !is_file($root . '/includes/database.php')) {
        throw new RuntimeException('Run from the website folder: cd ~/public_html');
    }
    if (!function_exists('token_get_all') || !function_exists('gzdecode') || !is_writable(dirname($root))) {
        throw new RuntimeException('PHP tokenizer, zlib and a writable folder outside public_html are required.');
    }
    if (stat($root)['dev'] !== stat(dirname($root))['dev']) {
        throw new RuntimeException('The website and backup folder must be on the same filesystem.');
    }
    $lockPath = dirname($root) . '/.weddingza-city-update.lock';
    if (is_link($lockPath)) {
        throw new RuntimeException('Cannot safely open the update lock.');
    }
    $lock = fopen($lockPath, 'c');
    if (!$lock || !flock($lock, LOCK_EX | LOCK_NB)) {
        throw new RuntimeException('Another city update is running. Try again after it finishes.');
    }
    chmod($lockPath, 0600);
    foreach ($manifest as $relativePath => $entry) {
        $path = $root . '/' . $relativePath;
        $parent = realpath(dirname($path));
        if (!$parent || !str_starts_with($parent . '/', $root . '/') || !is_writable($parent) || is_link($path)) {
            throw new RuntimeException('Unsafe or unwritable path: ' . $relativePath);
        }
        $compressed = base64_decode($entry['content_gzip_base64'], true);
        $updated = $compressed === false ? false : gzdecode($compressed);
        if ($updated === false || !hash_equals($entry['sha256'], hash('sha256', $updated))) {
            throw new RuntimeException('Invalid payload: ' . $relativePath);
        }
        if (str_ends_with($relativePath, '.php')) {
            token_get_all($updated, TOKEN_PARSE);
        }
        $original = is_file($path) ? file_get_contents($path) : null;
        if ($original === false || (file_exists($path) && (!is_file($path) || !is_writable($path)))) {
            throw new RuntimeException('Cannot read or update ' . $relativePath);
        }
        $originals[$relativePath] = $original;
        $modes[$relativePath] = $original !== null ? fileperms($path) & 0777 : 0644;
        if ($original !== null && hash_equals($entry['sha256'], hash('sha256', $original))) {
            continue;
        }
        if (($original === null && $entry['previous_sha256'] !== null)
            || ($original !== null && ($entry['previous_sha256'] === null
                || !hash_equals($entry['previous_sha256'], hash('sha256', $original))))) {
            throw new RuntimeException($relativePath . ' has a different version or local edits. No website files have been changed.');
        }
        $changes[$relativePath] = $updated;
    }
    if ($changes) {
        $backupDirectory = dirname($root) . '/weddingza-cities-backup-'
            . gmdate('Ymd-His') . '-' . bin2hex(random_bytes(4));
        if (!mkdir($backupDirectory, 0700)) {
            throw new RuntimeException('Cannot prepare the backup folder.');
        }
        foreach ($changes as $relativePath => $updated) {
            $backupFile = $backupDirectory . '/' . $relativePath;
            if (!is_dir(dirname($backupFile)) && !mkdir(dirname($backupFile), 0700, true)) {
                throw new RuntimeException('Cannot prepare the backup for ' . $relativePath);
            }
            $original = $originals[$relativePath];
            if ($original !== null && (file_put_contents($backupFile, $original) !== strlen($original) || !chmod($backupFile, 0600))) {
                throw new RuntimeException('Cannot back up ' . $relativePath);
            }
            $staged[$relativePath] = $backupFile . '.new';
            if (file_put_contents($staged[$relativePath], $updated) !== strlen($updated)
                || !chmod($staged[$relativePath], $modes[$relativePath])) {
                throw new RuntimeException('Cannot stage ' . $relativePath);
            }
        }
        // Recheck every destination before publishing any staged file.
        foreach ($originals as $relativePath => $original) {
            $path = $root . '/' . $relativePath;
            $current = is_file($path) ? file_get_contents($path) : null;
            if (is_link($path) || $current !== $original) {
                throw new RuntimeException('A file changed during preparation: ' . $relativePath);
            }
        }
        foreach ($changes as $relativePath => $updated) {
            if (!rename($staged[$relativePath], $root . '/' . $relativePath)) {
                throw new RuntimeException('Cannot install ' . $relativePath);
            }
            $installed[] = $relativePath;
        }
        echo "City discovery installed.\n";
        echo "Original files backed up in: " . $backupDirectory . "\n";
    } else {
        echo "City discovery is already installed.\n";
    }
    echo "Open https://weddingza.com/cities.php and refresh the homepage.\n";
} catch (Throwable $error) {
    $rollbackFailed = false;
    foreach (array_reverse($installed) as $relativePath) {
        if ($originals[$relativePath] === null) {
            $restored = unlink($root . '/' . $relativePath);
        } else {
            $restoreFile = $backupDirectory . '/' . $relativePath . '.restore';
            $restored = copy($backupDirectory . '/' . $relativePath, $restoreFile)
                && chmod($restoreFile, $modes[$relativePath])
                && rename($restoreFile, $root . '/' . $relativePath);
        }
        $rollbackFailed = $rollbackFailed || !$restored;
    }
    fwrite(STDERR, 'Update stopped: ' . $error->getMessage() . "\n");
    if ($installed) {
        fwrite(STDERR, $rollbackFailed
            ? 'Restore could not finish. Original files remain in: ' . $backupDirectory . "\n"
            : "Website changes were rolled back.\n");
    }
    exit(1);
} finally {
    if (is_resource($lock)) {
        flock($lock, LOCK_UN);
        fclose($lock);
    }
}
